import java.util.*;

public class Main {

    // 使用 DFS 统计一个连通块的大小
    public static int dfs(int start, int[][] g, boolean[] vis, int n) {
        Stack<Integer> stack = new Stack<>();
        stack.push(start);
        vis[start] = true;
        int cnt = 0;

        while (!stack.isEmpty()) {
            int u = stack.pop();
            cnt++;

            // 枚举所有列车，找与当前列车相对静止的点
            for (int v = 0; v < n; v++) {
                if (g[u][v] == 1 && !vis[v]) {
                    vis[v] = true;
                    stack.push(v);
                }
            }
        }

        return cnt;
    }

    // 题面要求实现的功能写在外部函数里
    public static int[] solve(int n, int[][] g) {
        boolean[] vis = new boolean[n];
        int mn = n;
        int mx = 1;

        // 枚举每个等价类
        for (int i = 0; i < n; i++) {
            if (!vis[i]) {
                int size = dfs(i, g, vis, n);
                mn = Math.min(mn, size);
                mx = Math.max(mx, size);
            }
        }

        return new int[]{mn, mx};
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // 输入
        int n = sc.nextInt();
        int[][] g = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                g[i][j] = sc.nextInt();
            }
        }

        // 求解
        int[] ans = solve(n, g);

        // 输出
        System.out.println(ans[0] + " " + ans[1]);
    }
}
