#include <iostream>
#include <vector>
#include <stack>
using namespace std;

// 使用 DFS 统计一个连通块的大小
int dfs(int start, const vector<vector<int>>& g, vector<bool>& vis, int n) {
    stack<int> st;
    st.push(start);
    vis[start] = true;
    int cnt = 0;

    while (!st.empty()) {
        int u = st.top();
        st.pop();
        cnt++;

        // 枚举所有列车，找与当前列车相对静止的点
        for (int v = 0; v < n; v++) {
            if (g[u][v] == 1 && !vis[v]) {
                vis[v] = true;
                st.push(v);
            }
        }
    }

    return cnt;
}

// 题面要求实现的功能写在外部函数里
pair<int, int> solve(int n, const vector<vector<int>>& g) {
    vector<bool> vis(n, false);
    int mn = n;
    int mx = 1;

    // 枚举每个等价类
    for (int i = 0; i < n; i++) {
        if (!vis[i]) {
            int size = dfs(i, g, vis, n);
            mn = min(mn, size);
            mx = max(mx, size);
        }
    }

    return {mn, mx};
}

int main() {
    // 输入
    int n;
    cin >> n;
    vector<vector<int>> g(n, vector<int>(n));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cin >> g[i][j];
        }
    }

    // 求解
    pair<int, int> ans = solve(n, g);

    // 输出
    cout << ans.first << " " << ans.second << endl;

    return 0;
}
